class TFMDrawFlowJsonCreatorRegistrationCollectors extends TFMDrawFlowJsonCreator
{
    Map                           blockContracts;
    Map							  depthMap;
    Set                           HeaderCollectors;
    Map                           blockname2Id;
    Map                           tracks;
    Map                           trackNodes2update;
    Map                           trackXs;
    Map                           nodeId2Collector;
    Map                           trackStarts;
    TFMLogicBlockCollection       collection;
    Map                           sectionContracts;
    TFMDrawFlowControlInteraction interactionClass;

    const int yPosAdjustment = 200;

}

